import { jsx as _jsx } from "react/jsx-runtime";
import { render, screen } from "@testing-library/react";
import { describe, it, expect } from "vitest";
import FormControlLabel from "@mui/material/FormControlLabel";
import Checkbox from "@mui/material/Checkbox";
import Switch from "@mui/material/Switch";
import "@testing-library/jest-dom/vitest";
import { testThemeConfigurations } from "./helpers";
import { RDSThemeProvider } from "../../../rdsThemeProvider";
describe("ThemedFormControlLabel Component", () => {
    testThemeConfigurations.forEach(({ themeName, themeMap, palettes }) => {
        Object.entries(palettes).forEach(([mode, palette]) => {
            describe(`${themeName} (${mode} mode)`, () => {
                const renderComponent = (props = {}) => render(_jsx(RDSThemeProvider, { themeMap: themeMap, themeMode: mode, children: _jsx(FormControlLabel, { control: _jsx(Checkbox, { color: props.error ? "error" : undefined }), label: "Test Label", ...props }) }));
                describe("Default State", () => {
                    ["checked", "unchecked"].forEach((state) => {
                        it(`applies correct styles for ${state} label`, () => {
                            const isChecked = state === "checked";
                            renderComponent({ checked: isChecked, variant: "outlined" });
                            const formControlLabel = document.querySelector(".MuiFormControlLabel-root");
                            const labelText = document.querySelector(".MuiFormControlLabel-label");
                            expect(screen.getByText("Test Label")).toBeDefined();
                            const expectedBackgroundColor = isChecked
                                ? palette.components.formControlLabel.background.selected
                                : palette.components.formControlLabel.background.main;
                            expect(formControlLabel).toHaveStyle({
                                backgroundColor: expectedBackgroundColor,
                            });
                            expect(formControlLabel).toHaveStyle({
                                border: `1px solid ${palette.components.formControlLabel.border.main}`,
                            });
                            expect(formControlLabel).toHaveStyle({
                                borderRadius: themeName.includes("Callisto") ? "8px" : "4px",
                            });
                            expect(labelText).toHaveStyle({
                                color: palette.components.formControlLabel.label.main,
                            });
                        });
                    });
                });
                describe("Switch default alignment", () => {
                    it("uses left-side label alignment by default", () => {
                        render(_jsx(RDSThemeProvider, { themeMap: themeMap, themeMode: mode, children: _jsx(FormControlLabel, { control: _jsx(Switch, {}), label: "Switch Label" }) }));
                        const formControlLabel = document.querySelector(".MuiFormControlLabel-root");
                        expect(formControlLabel).toHaveStyle({ marginLeft: "0px" });
                    });
                });
                describe("Disabled State", () => {
                    ["checked", "unchecked"].forEach((state) => {
                        it(`applies correct styles for ${state} disabled label`, () => {
                            const isChecked = state === "checked";
                            renderComponent({
                                checked: isChecked,
                                disabled: true,
                                variant: "outlined",
                            });
                            const formControlLabel = document.querySelector(".MuiFormControlLabel-root");
                            const labelText = document.querySelector(".MuiFormControlLabel-label");
                            expect(screen.getByText("Test Label")).toBeDefined();
                            expect(formControlLabel).toHaveStyle({
                                backgroundColor: palette.components.formControlLabel.background.disabled,
                            });
                            expect(formControlLabel).toHaveStyle({
                                border: `1px solid ${palette.components.formControlLabel.border.disabled}`,
                            });
                            expect(labelText).toHaveStyle({
                                color: palette.components.formControlLabel.label.disabled,
                            });
                        });
                    });
                });
                describe("Error State", () => {
                    ["checked", "unchecked"].forEach((state) => {
                        it(`applies correct styles for ${state} error label`, () => {
                            const isChecked = state === "checked";
                            renderComponent({
                                checked: isChecked,
                                error: true,
                                variant: "outlined",
                            });
                            const formControlLabel = document.querySelector(".MuiFormControlLabel-root");
                            const labelText = document.querySelector(".MuiFormControlLabel-label");
                            expect(formControlLabel).toHaveStyle({
                                backgroundColor: palette.components.formControlLabel.background.error,
                            });
                            expect(formControlLabel).toHaveStyle({
                                border: `1px solid ${palette.components.formControlLabel.border.error}`,
                            });
                            expect(labelText).toHaveStyle({
                                color: palette.error.main,
                            });
                        });
                    });
                });
            });
        });
    });
});
